def leftmost_index(sorted_values, target):
    """Return the index of the first occurrence of target in sorted_values,
    or -1 if absent. The input sequence must be sorted in ascending order."""
    low, high = 0, len(sorted_values) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if sorted_values[mid] < target:
            low = mid + 1
        elif sorted_values[mid] > target:
            high = mid - 1
        else:
            result = mid
            high = mid - 1  # continue searching left half for earlier occurrence
    return result

