def sort_versions(versions):
    """Sort a list of version strings by numeric MAJOR.MINOR.PATCH components.

    Args:
        versions: A list of version strings in the format "MAJOR.MINOR.PATCH".

    Returns:
        A new list of version strings sorted by numeric components.

    Raises:
        ValueError: If any version string is malformed.
    """
    # Validate all versions first
    for v in versions:
        parts = v.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version format: {v}")
        for part in parts:
            if not part.isdigit():
                raise ValueError(f"Invalid version format: {v}")

    # Sort by numeric components, preserving duplicates
    return sorted(versions, key=lambda v: tuple(int(x) for x in v.split('.')))

